sys_script_client.script:
function onLoad() {
    var ga = new GlideAjax('PulseBoxAIAB');
    ga.addParam('sysparm_name', 'getPendingSuggestions');
    ga.addParam('sysparm_target_table', g_form.getTableName());
    ga.addParam('sysparm_target_sys_id', g_form.getUniqueValue());
    ga.getXMLAnswer(function(answer) {
        if (!answer) return;
        var suggestions;
        try { suggestions = JSON.parse(answer); } catch (e) { return; }
        if (!suggestions || suggestions.length === 0) return;

        suggestions.forEach(function(s) {
            var funcName = s.field_name ? s.field_name.replace('script:', '') : '';
            var label = funcName ? funcName + '()': 'this record';
            var msg = '<b>' + s.agent_name + '</b> suggests changes to <b>' + label + '</b>';
            if (s.explanation) msg += ' &mdash; ' + s.explanation;
            msg += '&nbsp;&nbsp;<button type="button" class="btn btn-xs btn-primary" onclick="pulseReview(\x27' + s.sys_id + '\x27); return false;">Review</button>';
            g_form.addInfoMessage(msg);
        });
    });
}

window.pulseReview = function(sysId) {
    window.pulse_suggestion_id = sysId;
    var dialog = new GlideModal('pulsebox_review');
    dialog.setTitle('Code Review');
    dialog.setPreference('sysparm_suggestion_id', sysId);
    dialog.setWidth(900);
    dialog.render();
};
